package net.civeira.phylax.features.access.role.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.resourceserver.domain.ResourceServerReference;

class RoleFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_role_filter_builder() {
    RoleFilter filter = RoleFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getName().isPresent(),
        "Name must be empty if filter is build without it");
    filter.setName("one");
    Assertions.assertEquals("one", filter.getName().get(), "Name must be the same as the assigned");
    Assertions.assertFalse(filter.getResourceServer().isPresent(),
        "ResourceServer must be empty if filter is build without it");
    filter.setResourceServer(ResourceServerReference.of("$ref"));
    Assertions.assertEquals(ResourceServerReference.of("$ref"), filter.getResourceServer().get(),
        "ResourceServer must be the same as the assigned");
    Assertions.assertTrue(filter.getResourceServers().isEmpty(),
        "ResourceServers must be empty if filter is build without it");
    filter.setResourceServers(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getResourceServers(),
        "ResourceServers must be the same as the assigned");
  }

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test the filter of a unique index")
  void test_role_filter_by_resource_server_and_name() {
    RoleFilter filter =
        RoleFilter.byResourceServerAndName(ResourceServerReference.of("$ref"), "one");
    Assertions.assertEquals(ResourceServerReference.of("$ref"),
        filter.getResourceServer().orElse(null),
        "ResourceServer must be the one of the unique index");
    Assertions.assertEquals("one", filter.getName().orElse(null),
        "Name must be the one of the unique index");
  }
}
